}

/// Unit outward normal of the edge from `a` to `b`.
/// For a CCW polygon the outward normal is (dy, -dx) / len.
fn unit_normal(a: &Point64, b: &Point64, outward_sign: f64) -> (f64, f64) {
    let dx = (b.x - a.x) as f64;
    let dy = (b.y - a.y) as f64;
    let len = (dx * dx + dy * dy).sqrt();
    if len == 0.0 {
        return (0.0, 0.0);
    }
    (outward_sign * dy / len, outward_sign * -dx / len)
}

/// Intersection of the lines (p1 + t*d1) and (p2 + s*d2), if not parallel.
fn line_intersection(
    p1: (f64, f64),
    d1: (f64, f64),
    p2: (f64, f64),
    d2: (f64, f64),
) -> Option<(f64, f64)> {
    let cross = d1.0 * d2.1 - d1.1 * d2.0;
    if cross.abs() < 1e-12 {
        return None;
    }
    let t = ((p2.0 - p1.0) * d2.1 - (p2.1 - p1.1) * d2.0) / cross;
    Some((p1.0 + t * d1.0, p1.1 + t * d1.1))
}

/// Offset a single closed polygon by `delta` (positive expands).
/// Returns `None` for degenerate input (fewer than 3 distinct vertices).
fn offset_polygon(path: &Path64, delta: f64, join_type: JoinType) -> Option<Path64> {
    // Drop consecutive duplicate vertices.
    let mut pts: Vec<Point64> = Vec::with_capacity(path.len());
    for &p in path {
        if pts.last() != Some(&p) {
            pts.push(p);
        }
    }
    if pts.len() > 1 && pts.first() == pts.last() {
        pts.pop();
    }
    if pts.len() < 3 || delta == 0.0 {
        return None;
    }

    let n = pts.len();
    // CCW (positive area) => outward normal is (dy, -dx); flip for CW.
    let outward_sign = if signed_area(&pts) >= 0.0 { 1.0 } else { -1.0 };

    // Per-edge unit outward normals and direction vectors.
    let mut normals = Vec::with_capacity(n);
    let mut dirs = Vec::with_capacity(n);
    for i in 0..n {
        let a = pts[i];
        let b = pts[(i + 1) % n];
        normals.push(unit_normal(&a, &b, outward_sign));
        let dx = (b.x - a.x) as f64;
        let dy = (b.y - a.y) as f64;
        let len = (dx * dx + dy * dy).sqrt();
        dirs.push((dx / len, dy / len));
    }

    let mut out: Path64 = Vec::with_capacity(n);
    for i in 0..n {
        let v = (pts[i].x as f64, pts[i].y as f64);
        let prev = (i + n - 1) % n;
        let n1 = normals[prev]; // normal of incoming edge
        let n2 = normals[i]; // normal of outgoing edge

        // Offset lines adjacent to this vertex.
        let a1 = (v.0 + n1.0 * delta, v.1 + n1.1 * delta);
        let a2 = (v.0 + n2.0 * delta, v.1 + n2.1 * delta);

        let push_rounded = |out: &mut Path64, p: (f64, f64)| {
            out.push(Point64::new(p.0.round() as i64, p.1.round() as i64));
        };

        match line_intersection(a1, dirs[prev], a2, dirs[i]) {
            Some(m) => {
                let dist = ((m.0 - v.0).powi(2) + (m.1 - v.1).powi(2)).sqrt();
                let is_convex = (n1.0 + n2.0) * (m.0 - v.0) + (n1.1 + n2.1) * (m.1 - v.1) > 0.0;
                let limit = match join_type {
                    JoinType::Square => SQUARE_JOIN_MITER_LIMIT * delta.abs(),
                    JoinType::Miter => f64::INFINITY, // no practical clamp here
                    JoinType::Round => f64::INFINITY, // single-point approx is fine for our purposes
                };
                if is_convex && dist > limit {
                    // Square join: cut the corner with the two offset-edge
                    // endpoints shifted along each edge so the bevel sits at
                    // distance |delta| from the vertex bisector region.
                    let tan_half = (dist - delta.abs()) / delta.abs().max(1e-12);
                    let shift = (delta.abs() * tan_half.min(dist / delta.abs())).min(dist);
                    let s = shift.min(delta.abs()); // squared-off cut length
                    let p1 = (a1.0 + dirs[prev].0 * s, a1.1 + dirs[prev].1 * s);
                    let p2 = (a2.0 - dirs[i].0 * s, a2.1 - dirs[i].1 * s);
                    push_rounded(&mut out, p1);
                    push_rounded(&mut out, p2);
                } else {
                    push_rounded(&mut out, m);
                }
            }
            None => {
                // Parallel offset lines (spike / 180-degree corner): emit the
                // offset point of the outgoing edge.
                push_rounded(&mut out, a2);
            }
        }
    }

    if out.len() < 3 {
        return None;
    }
    Some(out)
}

/// Reimplementation of `Clipper2Lib::InflatePaths` for the closed-polygon
/// case used by the original program.
pub fn inflate_paths(paths: &Paths64, delta: f64, join_type: JoinType, end_type: EndType) -> Paths64 {
    let mut result: Paths64 = Vec::new();
    match end_type {
        EndType::Polygon => {
            for path in paths {
                if let Some(p) = offset_polygon(path, delta, join_type) {
                    result.push(p);
                }
            }
        }
        // Open-path end types are not exercised by the original program.
        _ => {}
    }
    result
}

